const questionnaire = document.querySelector('ds-agent-questionnaire')!;
questionnaire.questions = [{
  id: 'priority',
  type: 'single',
  question: 'Which issue should be first?',
  required: true,
  choices: [
    { value: 'battery', label: 'Repeated battery failures' },
    { value: 'tires', label: 'Overdue tire inspections' },
  ],
}];
questionnaire.addEventListener('dsAnswer', async event => {
  questionnaire.status = 'submitting';
  try {
    await submitAgentAnswers(event.detail);
    questionnaire.status = 'answered';
  } catch {
    questionnaire.status = 'error';
    questionnaire.errorMessage = 'Your answers could not be sent. Try again.';
  }
});

declare function submitAgentAnswers(detail: { requestId: string; answers: unknown[] }): Promise<void>;
